mapper.select:
SELECT mn.*, sc.c_name AS unitName, pp.p_name AS pName, cc.con_name AS conName, sp.post_name AS postName, rl.level_name AS levelName FROM safe_responsibility_post_person mn LEFT JOIN pre_project pp ON mn.p_id = pp.p_id LEFT JOIN Con_Contract cc ON mn.con_id = cc.con_id LEFT JOIN Sys_company sc ON mn.unit_id = sc.c_id LEFT JOIN safe_responsibility_post sp ON mn.post_id = sp.id LEFT JOIN safe_responsibility_level rl ON sp.level_id = rl.id
AND mn.id = #{request.id}
AND mn.p_id = #{request.pId}
AND mn.state = #{request.state}
AND mn.create_uid = #{request.createUid}
AND mn.con_id = #{request.conId}
AND mn.unit_id = #{request.unitId}
AND mn.post_id = #{request.postId}
AND pp.p_name LIKE CONCAT('%', #{request.pName}, '%')
AND cc.con_name LIKE CONCAT('%', #{request.conName}, '%')
AND mn.name LIKE CONCAT('%', #{request.name}, '%')
AND sc.c_name LIKE CONCAT('%', #{request.unitName}, '%')
AND sp.post_name LIKE CONCAT('%', #{request.postName}, '%')
AND rl.level_name LIKE CONCAT('%', #{request.levelName}, '%')
AND mn.job_category LIKE CONCAT('%', #{request.jobCategory}, '%')
AND mn.phone LIKE CONCAT('%', #{request.phone}, '%')
AND mn.certificate_number LIKE CONCAT('%', #{request.certificateNumber}, '%')
AND mn.create_uname LIKE CONCAT('%', #{request.createUname}, '%')
ORDER BY mn.sort_no ASC, mn.create_time DESC
